// Graduation check: the order logic, in plain JavaScript functions (no DOM needed).
const DELIVERY_FEE = 1000
const FREE_FROM = 15000
const naira = (n) => "₦" + n.toLocaleString("en-NG")

// 1. addToCart(cart, dish) → a NEW cart: +1 qty if the dish is there, else add it with qty 1 (don't mutate cart)
// 2. changeQty(cart, id, delta) → a NEW cart; rows reaching 0 are removed
// 3. totals(cart, mode) → { subtotal, delivery, total }: delivery ₦1,000 for "delivery" under ₦15,000, else 0
// 4. orderMessage(cart, mode) → "Order from Mama Put Kitchen:\nParty jollof × 2 = ₦7,000\nTotal: ₦8,000 (delivery)"
// 5. whatsappLink(number, text) → "https://wa.me/<number>?text=<encoded text>"

function addToCart(cart, dish) {
  return cart.some((i) => i.id === dish.id)
    ? cart.map((i) => (i.id === dish.id ? { ...i, qty: i.qty + 1 } : i))
    : [...cart, { id: dish.id, name: dish.name, price: dish.price, qty: 1 }]
}

function changeQty(cart, id, delta) {
  return cart.map((i) => (i.id === id ? { ...i, qty: i.qty + delta } : i)).filter((i) => i.qty > 0)
}

function totals(cart, mode) {
  const subtotal = cart.reduce((sum, i) => sum + i.price * i.qty, 0)
  const delivery = mode === "delivery" && subtotal < FREE_FROM ? DELIVERY_FEE : 0
  return { subtotal, delivery, total: subtotal + delivery }
}

function orderMessage(cart, mode) {
  return [
    "Order from Mama Put Kitchen:",
    ...cart.map((i) => `${i.name} × ${i.qty} = ${naira(i.price * i.qty)}`),
    `Total: ${naira(totals(cart, mode).total)} (${mode})`,
  ].join("\n")
}

function whatsappLink(number, text) {
  return `https://wa.me/${number}?text=${encodeURIComponent(text)}`
}
